(async()=>{const fs=require('fs');const txt=fs.readFileSync('.env.local','utf8');const env={};for(const line of txt.split(/\r?\n/)){if(!line||line.startsWith('#'))continue;const i=line.indexOf('=');if(i<0)continue;env[line.slice(0,i).trim()]=line.slice(i+1).trim();}const url=env.NEXT_PUBLIC_SUPABASE_URL;const key=env.NEXT_PUBLIC_SUPABASE_ANON_KEY;const h={apikey:key,Authorization:'Bearer '+key,Prefer:'count=exact'};async function get(path){const res=await fetch(url+'/rest/v1/'+path,{headers:h});const text=await res.text();let json=null;try{json=JSON.parse(text);}catch{}return {status:res.status,range:res.headers.get('content-range')||'n/a',json,text};}
const requested=['circuits','circuit_contents','circuit_destinations','circuit_images','circuit_concepts','destinations','destination_contents','destination_highlights','destination_highlight_contents','destination_practical_items','destination_faq_items','destination_faq_item_contents','destination_itineraries','destination_itinerary_stops','destination_itinerary_contents','destination_rankings','destination_scores','cities','city_highlights','city_images','city_tags','knowledge_items','knowledge_entities','knowledge_relations','knowledge_sources','knowledge_item_sources','knowledge_definitions','knowledge_categories','knowledge_indicators','knowledge_analyses','analysis_definitions','analysis_kpis','analysis_reports','missions','mission_candidates','ai_entities','ai_outputs','ai_decisions','ai_generation_jobs','ai_learning_events'];
for(const t of requested){const r=await get(t+'?select=*&limit=2');let cols='';if(Array.isArray(r.json)&&r.json.length>0){cols=Object.keys(r.json[0]).join(',');}else if(Array.isArray(r.json)){cols='NO_ROWS_OR_HIDDEN';}else if(r.json&&r.json.message){cols='ERR:'+r.json.message;}else{cols='NON_JSON';}console.log('TABLE',t,'STATUS',r.status,'RANGE',r.range,'COLS',cols);}
const city=await get('cities?select=id,name,slug,status,country_id,administrative_area_id,recommended_city_slugs,ideal_visit_duration,best_visit_period,population&slug=eq.beaucaire&limit=1');console.log('BEAUCAIRE_CITY',JSON.stringify(city.json));
let cityId='';if(Array.isArray(city.json)&&city.json[0]?.id) cityId=city.json[0].id;
if(cityId){const d=await get('destinations?select=id,slug,city_id,country_id,administrative_area_id,poi_id&city_id=eq.'+cityId+'&limit=3');console.log('BEAUCAIRE_DESTINATIONS',JSON.stringify(d.json));let did='';if(Array.isArray(d.json)&&d.json[0]?.id) did=d.json[0].id; if(did){const q1=await get('destination_contents?select=destination_id,language_id,title,subtitle,short_description,seo_title&destination_id=eq.'+did+'&limit=3');console.log('BEAUCAIRE_CONTENTS',JSON.stringify(q1.json));const q2=await get('destination_highlights?select=id,destination_id,poi_id,position,duration_minutes&destination_id=eq.'+did+'&order=position.asc&limit=6');console.log('BEAUCAIRE_HIGHLIGHTS',JSON.stringify(q2.json));const q3=await get('destination_practical_items?select=id,destination_id,position&destination_id=eq.'+did+'&order=position.asc&limit=6');console.log('BEAUCAIRE_PRACTICAL_ITEMS',JSON.stringify(q3.json));const q4=await get('destination_faq_items?select=id,destination_id,position&destination_id=eq.'+did+'&order=position.asc&limit=6');console.log('BEAUCAIRE_FAQ_ITEMS',JSON.stringify(q4.json));const q5=await get('destination_itineraries?select=id,destination_id,position&destination_id=eq.'+did+'&order=position.asc&limit=6');console.log('BEAUCAIRE_ITINERARIES',JSON.stringify(q5.json)); }}
})();
